import React, { useState, useEffect } from "react";
import { collection, getDocs } from "firebase/firestore";
import { db } from "../../firebaseConfig";
import "./ManageStudents.css";

const AdminViewStudents = () => {
  const [students, setStudents] = useState([]);

  const StudentsCollectionRef = collection(db, "students");

  // Fetch students from Firestore and sort alphabetically by name
  const fetchStudents = async () => {
    const data = await getDocs(StudentsCollectionRef);
    const studentsData = data.docs.map((doc) => ({ ...doc.data(), id: doc.id }));

    // Sort students alphabetically by name
    studentsData.sort((a, b) => a.name.localeCompare(b.name));

    setStudents(studentsData);
  };

  useEffect(() => {
    fetchStudents();
  }, []);

  return (
    <div className="manage-students-container">
      <h2>View Registered Students</h2>
      <table className="students-table">
        <thead>
          <tr>
            <th>Name</th>
            <th>Email</th>
            <th>Class</th>
          </tr>
        </thead>
        <tbody>
          {students.length === 0 ? (
            <tr>
              <td colSpan="3">No students registered yet.</td>
            </tr>
          ) : (
            students.map((student) => (
              <tr key={student.id}>
                <td>{student.name}</td>
                <td>{student.email}</td>
                <td>{student.slass}</td>
              </tr>
            ))
          )}
        </tbody>
      </table>
    </div>
  );
};

export default AdminViewStudents;
